"use strict";(globalThis.webpackChunkmy_website||=[]).push([[17681],{97272(t){t.exports=JSON.parse('{"slug":"redeemer","title":"Redeemer","short":"Data supplied by the spending transaction that tells a smart contract what action is being attempted.","category":"smart-contracts","aliases":[],"mentalModel":"The action you announce when trying to spend a contract-locked UTxO: \'I want to do X.\' The script either nods or refuses.","related":["datum","validator","eutxo","smart-contract"],"sources":[],"link":null,"level":"intermediate","body":"Data supplied by the transaction that tries to spend a smart-contract-locked output. The redeemer answers the question \\"what is this transaction trying to do?\\", while the datum answers \\"what state is currently attached to this output?\\". The script evaluates both together and either authorizes or rejects the spend."}')}}]);